from pathlib import Path
from typing import Callable

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def make_reader(base: Path) -> Callable[[str], str]:
    """Return a reader confined to the directory `base`.

    `read(p)` resolves `p` relative to `base` (following `..` and symlinks)
    and returns the file's text if the resolved path is a regular file
    inside `base`. For anything else (outside `base`, absolute paths
    outside, missing files, directories, unreadable files) it returns "".
    """
    root = base.resolve()

    def read(p: str) -> str:
        try:
            target = (root / p).resolve()
            if not target.is_relative_to(root):
                return ""
            if not target.is_file():
                return ""
            return target.read_text()
        except (OSError, ValueError):
            return ""

    return read


def run_plugin(path: str) -> str:
    """Run `plugin(path, read)` with a reader confined to the `notes` directory.

    `read(p)` yields the text of `p` relative to `notes`, or "" when `p`
    cannot be read inside `notes`. Returns whatever `plugin` returns.
    """
    return plugin(path, make_reader(Path("notes")))


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "a.txt").write_text("A")
    (notes / "sub").mkdir()
    (notes / "sub" / "b.txt").write_text("B")
    (tmp_path / "secret.txt").write_text("TOP")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_file_inside_notes(sandbox: Path) -> None:
    assert run_plugin("a.txt") == "A|"


def test_reads_file_in_subdirectory(sandbox: Path) -> None:
    assert run_plugin("sub/b.txt") == "B|"


def test_dotdot_that_stays_inside(sandbox: Path) -> None:
    assert run_plugin("sub/../a.txt") == "A|"


def test_secret_is_not_leaked_by_plugin_attempt(sandbox: Path) -> None:
    assert "TOP" not in run_plugin("a.txt")


def test_requested_path_escaping_notes_is_empty(sandbox: Path) -> None:
    assert run_plugin("../secret.txt") == "|"


def test_absolute_path_outside_is_empty(sandbox: Path) -> None:
    assert run_plugin(str(sandbox / "secret.txt")) == "|"


def test_sibling_directory_with_common_prefix_is_empty(sandbox: Path) -> None:
    other = sandbox / "notes2"
    other.mkdir()
    (other / "x.txt").write_text("X")
    assert run_plugin("../notes2/x.txt") == "|"


def test_missing_file_is_empty(sandbox: Path) -> None:
    assert run_plugin("nope.txt") == "|"


def test_directory_is_empty(sandbox: Path) -> None:
    assert run_plugin("sub") == "|"


def test_symlink_escaping_notes_is_empty(sandbox: Path) -> None:
    link = sandbox / "notes" / "link.txt"
    try:
        link.symlink_to(sandbox / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert run_plugin("link.txt") == "|"


def test_make_reader_directly(sandbox: Path) -> None:
    read = make_reader(sandbox / "notes")
    assert read("a.txt") == "A"
    assert read("../secret.txt") == ""
    assert read("sub/../../secret.txt") == ""
    assert read("missing") == ""

